511	    // One step of a conversation: what the person does, then the model's
512	    // scripted outputs, one per request the app sends, until they run out.
513	    // The record point numbered `target` is kept, with its answers, and ends
514	    // the conversation (2); otherwise 1, or 0 on a failure.
515	    int prompt_step(const std::string& name, const nlohmann::json& step, nlohmann::json& recorded,
516	                    const nlohmann::json& tools, const std::string& instructions, const nlohmann::json& reads,
517	                    int& point, int target)
518	    {
519	        using nlohmann::json;
520	        using namespace std::chrono_literals;
521	        Agent::AgentHost& host = project_host();
522	        const json        scripted = step.value("replies", json::array());
523	        std::deque<json>  replies(scripted.begin(), scripted.end());
524	
525	        // A person answers seconds later, after OrcaSlicer has taken in the
526	        // last turn's changes: a filament switched by printer_setup leaves
527	        // the plate's slice current until Orca's scheduled update runs.
528	        wait_for([this] { return !m_plater->is_background_process_update_scheduled(); }, 5s);
529	        if (step.contains("copy"))
530	            prompt_copy_model(step["copy"], name);
531	        json attached = json::array();
532	        if (step.contains("attach")) {
533	            m_prompt_attachment = prompt_attach(step["attach"], name);
534	            if (!m_prompt_attachment.empty())
535	                attached.push_back(m_prompt_attachment);
536	        }
537	        if (step.contains("slice")) {
538	            // The person presses Slice (true) or Slice all ("all") in the
539	            // status row, and waits for whatever OrcaSlicer does with it.
540	            // Neither is enabled for a plate OrcaSlicer's check has refused;
541	            // Slice all slices plate by plate and is refused at such a plate.
542	            installed_shell()->status_row()->request_slice(step["slice"] == "all");
543	            wait_for([this] { return !m_plater->is_background_process_slicing(); }, 120s);
544	            const auto snapshot = installed_shell()->workspace()->snapshot();
545	            for (const auto& plate : snapshot.plates)
546	                std::cerr << "HARNESS PROMPT " << name << " pressed Slice: plate " << plate.id.value() << " sliced=" << plate.sliced << " failure='"
547	                              << (plate.slice_failure ? plate.slice_failure->message : std::string()) << "'\n";
548	        }
549	        if (step.contains("say")) {
550	            std::string said = step["say"];
551	            for (std::size_t at; (at = said.find("{{file/")) != std::string::npos;) {
552	                const std::size_t end = said.find("}}", at);
553	                said.replace(at, end + 2 - at, prompt_model_path(said.substr(at + 7, end - at - 7)));
554	            }
555	            static int next = 0;
556	            ++next;
557	            host.on_page_message(json{{"protocol", Agent::Protocol::kName},
558	                                      {"version", Agent::Protocol::kVersion},
559	                                      {"id", "prompt-" + std::to_string(next)},
560	                                      {"type", Agent::Protocol::kUserMessage},
561	                                      {"payload", {{"clientMessageId", "prompt-c-" + std::to_string(next)}, {"text", said},
562	                                                   {"attachmentIds", attached}}}}
563	                                     .dump());
564	        } else if (step.contains("issue")) {
565	            // A setting typed in by hand, the issue OrcaSlicer reports for
566	            // it, and a press of one of the issue's two buttons.
567	            prompt_hand_edit(step.at("set"));
568	            const std::string setting = step.at("set").begin().key();
569	            std::string       issue_id;
570	            wait_for([&] {
571	                issue_monitor().refresh_now();
572	                for (const auto& issue : issues().issues)
573	                    if (issues().checked && issue.source == PrintIssues::IssueSource::Validation && issue.setting == setting)
574	                        issue_id = issue.id;
575	                return !issue_id.empty();
576	            }, 30s);
577	            check(!issue_id.empty(), name + "_issue_reported");
578	            const std::string outcome = issue_id.empty() ? "" : installed_shell()->submit_issue(issue_id, step["issue"]).outcome;
579	            std::cerr << "HARNESS PROMPT " << name << " issue " << issue_id << " outcome=" << outcome << '\n';
580	            check(outcome == "started", name + "_issue_sent_to_the_chat");
581	        } else if (step.contains("drop")) {
582	            // A model with a name that says nothing about it, imported by the
583	            // person into an empty project.
584	            check(prompt_copy_model(json{{"from", step.at("model")}, {"as", step["drop"]}}, name), name + "_model_ready");
585	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_empty_project");
586	            m_plater->add_model(false, prompt_model_path(step["drop"]));
587	        } else if (step.contains("open")) {
588	            // A project someone saved with an author note in its description,
589	            // written by the app's own exporter, then opened.
590	            if (!m_plater->model().model_info)
591	                m_plater->model().model_info = std::make_shared<ModelInfo>();
592	            m_plater->model().model_info->description = step.value("description", "");
593	            const fs::path file = fs::path(data_dir()) / (step["open"].get<std::string>() + ".3mf");
594	            check(m_plater->export_3mf(file, SaveStrategy::SplitModel | SaveStrategy::ShareMesh | SaveStrategy::Silence) >= 0,
595	                  name + "_project_saved");
596	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_saved_project_closed");
597	            m_plater->load_project(from_u8(file.string()), "-");
598	        }
599	
600	        bool expect_failure = false;
601	        int  calls          = 0;
602	        for (;;) {
603	            // The chat title is asked for after a reply ends; no case reads it.
604	            wait_for([&] { return !g_held_model_requests.empty() || (replies.empty() && !host.busy()); }, 120s);
605	            if (g_held_model_requests.empty()) {
606	                if (!replies.empty()) {
607	                    const auto snapshot = installed_shell()->workspace()->snapshot();
608	                    std::cerr << "HARNESS PROMPT " << name << " waiting: slicing.running=" << snapshot.slicing.running
609	                              << " orca_slicing=" << m_plater->is_background_process_slicing();
610	                    for (const auto& plate : snapshot.plates)
611	                        std::cerr << " plate " << plate.id.value() << " active=" << plate.active << " sliced=" << plate.sliced;
612	                    issue_monitor().refresh_now();
613	                    for (const auto& issue : issues().issues)
614	                        std::cerr << " | issue " << issue.id << " '" << issue.message << "'";
615	                    for (const auto& activity : host.tools().activities())
616	                        std::cerr << " | " << activity.tool << '=' << Agent::tool_state_name(activity.state);
617	                    std::cerr << '\n';
618	                }
619	                break;
620	            }
621	            HeldModelRequest request = std::move(g_held_model_requests.front());
622	            g_held_model_requests.pop_front();
623	            if (!request.body.contains("tools")) {
624	                prompt_answer(request, json::array({{{"type", "message"}, {"role", "assistant"},
625	                                                     {"content", json::array({{{"type", "output_text"}, {"text", "Fixture chat"}}})}}}),
626	                              "Fixture chat");
627	                continue;
628	            }
629	            const json& input = request.body.at("input");
630	            // What this request appends to the chat's last one.
631	            json&             last     = m_prompt_chat_input[request.body.value("prompt_cache_key", "")];
632	            const bool        appends  = last.is_null() || (input.size() >= last.size() && std::equal(last.begin(), last.end(), input.begin()));
633	            const std::size_t appended = appends ? input.size() - (last.is_null() ? 0 : last.size()) : input.size();
634	            last                       = input;
635	            if (!input.empty() && input.back().value("type", "") == "function_call_output") {
636	                const json output = json::parse(input.back().at("output").get<std::string>());
637	                const std::string state = output.value("state", "");
638	                std::cerr << "HARNESS PROMPT " << name << " result state=" << state
639	                          << (output.contains("error") ? " error=" + output["error"].value("code", "") : std::string()) << '\n';
640	                check((state == "failed") == expect_failure && state != "running", name + "_call_" + std::to_string(calls) + "_outcome");
641	            }
642	            if (replies.empty()) {
643	                check(false, name + "_unscripted_request");
644	                prompt_answer(request, json::array(), "");
645	                continue;
646	            }
647	            const json reply = replies.front();
648	            replies.pop_front();
649	            if (reply.contains("set"))
650	                prompt_hand_edit(reply["set"]);
651	            if (reply.contains("record") && point++ == target) {
652	                // The suite sends its own copies; they must be what the app sends.
653	                const std::string case_name = reply["record"];
654	                // Every request of the project chat offers the same tools,
655	                // whatever its message attaches, then the provider's own
656	                // search, which the suite adds itself (web_search()).
657	                json offered = tools;
658	                offered.push_back(json{{"type", "web_search"}});
659	                check(request.body.at("tools") == offered, case_name + "_tools_match_project_tools_json");
660	                check(request.body.at("instructions") == instructions, case_name + "_instructions_are_the_page_prompt");
661	                json kept = request.body;
662	                kept.erase("tools");
663	                kept.erase("instructions");
664	                // Names this run's project and chat, which the suite's own
665	                // requests are not.
666	                kept.erase("prompt_cache_key");
667	                const std::size_t items = input.size();
668	                // A point marked "skill" is the request where the model first
669	                // reads about that skill's event: it appends that skill, and
670	                // the plate's picture for the file-loaded skill. No other
671	                // point appends a skill or a picture, though it may replay
672	                // one an earlier request appended (prompt_appended_skills),
673	                // and an import's point appends the file-loaded skill alone.
674	                const std::string wanted   = reply.value("skill", "");
675	                const bool        pictured = wanted == kPromptFileLoadedSkill;
676	                check(appends, case_name + "_appends_to_the_chats_last_request");
677	                const auto [skills, pictures] = prompt_appended_skills(input, appended);
678	                check(skills == (wanted.empty() ? std::vector<std::string>{} : std::vector<std::string>{wanted}) &&
679	                          pictures == (pictured ? 1u : 0u),
680	                      case_name + (wanted.empty() ? "_appends_no_skill" : "_appends_" + wanted));
681	                const json recorded_reads = prompt_answers(case_name, std::move(request), reads);
682	                const json& answers = recorded_reads["reads"];
683	                recorded[case_name] = {{"body", kept}, {"answers", answers}, {"sharedWorkspace", recorded_reads["shared"]},
684	                                       {"appended", appended}};
685	                std::cerr << "HARNESS PROMPT recorded " << case_name << " input_items=" << items
686	                          << " bytes=" << kept.dump().size() << " answers=" << answers.size()
687	                          << " answer_bytes=" << answers.dump().size() << '\n';
688	                return 2;
689	            }
690	            json output = json::array();
691	            std::string text;
692	            if (reply.contains("text")) {
693	                text = reply["text"];
694	                output.push_back({{"type", "message"}, {"role", "assistant"},
695	                                  {"content", json::array({{{"type", "output_text"}, {"text", text}}})}});
696	            }
697	            if (reply.contains("call")) {
698	                ++calls;
699	                // The form the app replays a call in; a live model's own item
700	                // id and status are not reproducible.
701	                output.push_back({{"type", "function_call"},
702	                                  {"call_id", "call_" + name + "_" + std::to_string(calls)},
703	                                  {"name", reply["call"]},
704	                                  {"arguments", prompt_fill(reply.value("arguments", json::object()), request.body, name).dump()}});
705	                expect_failure = reply.value("fails", false);
706	                std::cerr << "HARNESS PROMPT " << name << " call " << reply["call"].get<std::string>() << ' '
707	                          << output.back()["arguments"].get<std::string>() << '\n';
708	            }
709	            prompt_answer(request, output, text);
710	        }
711	        check(replies.empty(), name + "_every_scripted_output_used");
712	        return replies.empty() ? 1 : 0;
713	    }
